const ICONS={
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',mission:'<path d="M9 4h6l1 2h3a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h3z"/><path d="m9 13 2 2 4-4"/>',drone:'<circle cx="5" cy="6" r="2"/><circle cx="19" cy="6" r="2"/><circle cx="5" cy="18" r="2"/><circle cx="19" cy="18" r="2"/><path d="M7 7.5 10 10M17 7.5 14 10M7 16.5 10 14M17 16.5 14 14"/><rect x="9" y="9" width="6" height="6" rx="2"/>',shield:'<path d="M12 3 4.5 6v5.5c0 4.6 3 7.8 7.5 9.5 4.5-1.7 7.5-4.9 7.5-9.5V6z"/><path d="m9 12 2 2 4-4"/>',record:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h6M9 16h3"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1l2-1-2-4-2 1a8 8 0 0 0-2-1l-.3-2h-5l-.3 2a8 8 0 0 0-2 1l-2-1-2 4 2 1a7 7 0 0 0 0 2l-2 1 2 4 2-1a8 8 0 0 0 2 1l.3 2h5l.3-2a8 8 0 0 0 2-1l2 1 2-4-2-1c.1-.3.1-.7.1-1z"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15M15 6v15"/>',alert:'<path d="M12 3 2.5 20h19z"/><path d="M12 9v4M12 17h.01"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12M7 10l5 5 5-5M5 21h14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',battery:'<rect x="3" y="7" width="17" height="10" rx="2"/><path d="M21 10v4M7 10v4M11 10v4M15 10v4"/>',play:'<path d="m8 5 11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',rth:'<path d="M3 7v6h6M4.5 16a8 8 0 1 0 .5-9L3 9"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="M6 6l12 12M18 6 6 18"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',route:'<circle cx="6" cy="18" r="2"/><circle cx="18" cy="6" r="2"/><path d="M8 18h4a4 4 0 0 0 4-4V8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4H4v12h4"/>'
};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.info}</svg>`;}
const NAV=[['dashboard','관제현황','grid'],['missions','임무관리','mission'],['assets','기체·배터리','drone'],['safety','안전·경보','shield'],['records','운영기록','record'],['settings','시스템설정','settings']];
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
let missionQuery='',missionFilter='ALL',missionDraftStep=1,lastSimulationAt=0;
const root=$('#app');

function toast(title,message='',type='info',duration=3600){const el=document.createElement('div');el.className=`toast ${type}`;el.innerHTML=`<strong>${escapeHtml(title)}</strong>${message?`<p>${escapeHtml(message)}</p>`:''}`;$('#toast-root').appendChild(el);setTimeout(()=>el.remove(),duration);}
function pageHead(eyebrow,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${icon('grid')} ${escapeHtml(eyebrow)}</div><h1>${escapeHtml(title)}</h1><p>${escapeHtml(description)}</p></div><div class="actions">${actions}</div></div>`;}
function kpi(label,value,unit,foot,tone=''){return `<article class="kpi ${tone}"><div class="kpi-label">${escapeHtml(label)}</div><div class="kpi-value mono">${escapeHtml(value)}<small>${escapeHtml(unit)}</small></div><div class="kpi-foot">${foot}</div></article>`;}
function render(){DLogisMap.destroy();let html='';if(!state.session.role)html=welcomeView();else if(state.session.role==='pilot')html=pilotView();else if(state.session.role==='recipient')html=recipientView();else html=adminShell();root.innerHTML=html;updateClock();if(state.session.role==='admin'&&state.ui.view==='dashboard')requestAnimationFrame(()=>DLogisMap.render());}
function welcomeView(){const roles=[['admin','관제센터','주문·임무·지도·기체·배터리·경보·운영기록을 통합 관리합니다.','grid','관제센터 시작'],['pilot','현장 조종자','오늘의 임무와 안전점검을 순서대로 수행하고 관제 명령을 확인합니다.','drone','조종자 화면'],['recipient','배송 수령인','예상 도착시간, 배송 진행상태와 수령코드를 한 화면에서 확인합니다.','mission','배송조회 화면']];return `<main class="welcome"><div class="welcome-panel"><div class="welcome-brand"><div class="brand-mark">${icon('drone')}</div><div><h1>D-LOGIS CONTROL V3</h1><p>정밀 데이터 기록 기반 드론 배송 통합관제시스템</p></div></div><section class="role-grid">${roles.map(([role,title,desc,ic,button])=>`<button class="role-card" data-enter-role="${role}"><span class="role-icon">${icon(ic)}</span><h2>${title}</h2><p>${desc}</p><span class="btn primary">${button}</span></button>`).join('')}</section></div></main>`;}
function adminShell(){const views={dashboard:dashboardView,missions:missionsView,assets:assetsView,safety:safetyView,records:recordsView,settings:settingsView},view=views[state.ui.view]||dashboardView,unack=state.alerts.filter(a=>!a.acknowledged).length;return `<div class="app-shell"><aside class="sidebar ${state.ui.sidebarOpen?'open':''}"><div class="brand"><div class="brand-mark">${icon('drone')}</div><div class="brand-copy"><strong>D-LOGIS</strong><small>CONTROL V3</small></div></div><div class="nav-label">OPERATIONS</div><nav class="nav">${NAV.map(([id,label,ic])=>`<button class="nav-btn ${state.ui.view===id?'active':''}" data-view="${id}">${icon(ic)}<span>${label}</span>${id==='safety'&&unack?`<span class="count">${unack}</span>`:''}</button>`).join('')}</nav><div class="sidebar-status"><div class="nav-label">SYSTEM STATUS</div><div class="system-line"><i></i><span>관제 UI</span><span>정상</span></div><div class="system-line"><i></i><span>텔레메트리</span><span>${fmt1(dataFreshness(),'초')}</span></div><div class="system-line"><i></i><span>보고서 모듈</span><span>XLSX</span></div><div class="system-line"><i></i><span>지도</span><span>${state.settings.mapProvider==='kakao'?'Kakao':'OSM'}</span></div><div class="side-weather"><span>${icon('alert')}</span><div><strong>비행 적합</strong><small>풍속 3.2 m/s</small></div><b>27.4°</b></div></div></aside><header class="topbar"><button class="btn icon mobile-menu" data-sidebar-toggle>${icon('menu')}</button><span class="site-pill">${icon('map')} ${escapeHtml(state.meta.centerName)}</span><span class="network-pill ${operationalStatus()==='warning'?'warning':''}"><i class="live-dot"></i>${operationalStatus()==='warning'?'조치 확인 필요':'관제망 정상'} · ${fmt1(dataFreshness(),'초')}</span><div class="clock-box"><strong id="live-clock">--:--:--</strong><small id="live-date">----</small></div><button class="profile-btn" data-role-menu><span class="avatar">관</span><span class="profile-copy"><strong>${escapeHtml(state.session.operatorName)}</strong><small>${escapeHtml(state.session.operatorRole)}</small></span></button></header><main class="main">${view()}</main></div>`;}
function dashboardActions(){return `<button class="btn" data-export-xlsx>${icon('download')} 운영보고서 XLSX</button><button class="btn primary" data-new-mission>${icon('plus')} 신규 배송임무</button>`;}
function dashboardView(){const active=activeMissions(),available=state.drones.filter(d=>d.airworthy&&['READY','IN_FLIGHT','RETURNING','HOLDING'].includes(d.status)).length,safeBats=state.batteries.filter(b=>b.status!=='QUARANTINE'&&b.soh>=85&&b.cellDeltaMv<=50).length,stale=dataFreshness()>state.settings.telemetryIntervalSec*3,selected=missionById(state.ui.selectedMissionId)||active[0]||state.missions[0];return `${pageHead('LIVE OPERATIONS','드론 배송 통합관제','조치가 필요한 항목을 먼저 보여주고, 모든 수치·시각·명령·점검 이력을 Mission ID로 기록합니다.',dashboardActions())}<section class="grid kpi-grid">${kpi('즉시 확인 항목',actionableCount().toFixed(1),'건','<span class="trend">우선순위 기반</span>','tone-red')}${kpi('진행 중 임무',active.length.toFixed(1),'건',`예약 포함 ${state.missions.filter(m=>!['COMPLETED','CANCELLED'].includes(m.status)).length.toFixed(1)}건`)}${kpi('정시 배송률',onTimeRate().toFixed(1),'%',`완료 ${state.missions.filter(m=>m.status==='COMPLETED').length.toFixed(1)}건`,'tone-green')}${kpi('운항 가능 기체',available.toFixed(1),'대',`전체 ${state.drones.length.toFixed(1)}대`,'tone-green')}${kpi('임무 적합 배터리',safeBats.toFixed(1),'개',`격리 ${state.batteries.filter(b=>b.status==='QUARANTINE').length.toFixed(1)}개`,'tone-amber')}${kpi('데이터 신선도',dataFreshness().toFixed(1),'초',stale?'<span style="color:var(--amber-700);font-weight:800">수신 지연 확인</span>':'<span class="trend">정상 수신</span>',stale?'tone-amber':'tone-green')}</section><section class="grid dashboard-grid">${mapCard(selected)}${actionQueueCard()}</section><section class="section-gap">${activeMissionStrip(active)}</section><section class="card section-gap">${telemetryTable()}</section>`;}
function mapCard(mission){const drone=droneById(mission?.droneId),battery=batteryById(mission?.batteryId);return `<article class="card map-card"><div class="card-head"><div class="card-title"><span class="card-icon">${icon('map')}</span><div><h2>실시간 운항 지도</h2><p>WGS84 위치 · 승인항로 · 기체 상태</p></div></div><div class="map-toolbar"><select class="select" id="quick-map-provider"><option value="kakao" ${state.settings.mapProvider==='kakao'?'selected':''}>카카오맵 무료모드</option><option value="osm" ${state.settings.mapProvider==='osm'?'selected':''}>OpenStreetMap</option></select><button class="btn small" data-open-kakao>카카오맵 열기</button></div></div><div class="map-wrap"><div id="ops-map"></div><div class="map-status"><span class="map-chip">풍속 ${fmt1(3.2,' m/s')}</span><span class="map-chip">가시거리 ${fmt1(12.4,' km')}</span><span class="map-chip">수신 ${fmt1(dataFreshness(),'초 전')}</span></div>${mission?`<div class="map-info"><div class="map-info-head"><h3>${escapeHtml(drone?.name||'미배정')} · ${escapeHtml(mission.title)}</h3>${statusBadge(mission.status)}</div><div class="map-info-grid"><div><span>고도</span><strong>${fmt1(drone?.altitudeM,' m')}</strong></div><div><span>속도</span><strong>${fmt1(drone?.groundSpeedKmh,' km/h')}</strong></div><div><span>배터리</span><strong>${fmt1(battery?.soc,'%')}</strong></div><div><span>통신</span><strong>${fmt1(drone?.linkQualityPct,'%')}</strong></div></div><div class="map-provider-note">화면 좌표: ${coordToDms(drone?.lat||0,true)} · ${coordToDms(drone?.lng||0,false)}</div></div>`:''}</div></article>`;}
function buildActionQueue(){const rows=[];state.alerts.filter(a=>!a.acknowledged).forEach(a=>rows.push({type:'alert',severity:a.severity,title:a.title,message:a.message,time:a.createdAt,id:a.id}));state.missions.filter(m=>m.status==='PENDING_APPROVAL').forEach(m=>rows.push({type:'mission',severity:m.priority==='URGENT'?'CRITICAL':'WARNING',title:'운항 승인 대기',message:`${m.id} · ${m.title}`,time:m.createdAt,id:m.id}));state.batteries.filter(b=>b.status!=='QUARANTINE'&&(b.soh<85||b.cellDeltaMv>50)).forEach(b=>rows.push({type:'battery',severity:'CRITICAL',title:'배터리 임무투입 차단 권고',message:`${b.id} · SOH ${fmt1(b.soh,'%')} · 셀편차 ${fmt1(b.cellDeltaMv,' mV')}`,time:b.lastInspectionAt,id:b.id}));const rank={CRITICAL:0,WARNING:1,INFO:2};return rows.sort((a,b)=>rank[a.severity]-rank[b.severity]||new Date(b.time)-new Date(a.time));}
function actionQueueCard(){const rows=buildActionQueue().slice(0,6);return `<article class="card"><div class="card-head"><div class="card-title"><span class="card-icon">${icon('alert')}</span><div><h2>조치 우선순위</h2><p>경보·승인·자산 상태를 중요도순으로 정렬</p></div></div><span class="status ${rows.some(r=>r.severity==='CRITICAL')?'red':'amber'}">${rows.length}건</span></div><div class="card-body"><div class="queue">${rows.length?rows.map(r=>`<div class="queue-row"><i class="severity ${r.severity}"></i><div class="queue-copy"><strong>${escapeHtml(r.title)}</strong><p>${escapeHtml(r.message)}</p><small>${fmtKST(r.time,true)}</small></div>${r.type==='alert'?`<button class="btn small" data-ack-alert="${r.id}">확인</button>`:r.type==='mission'?`<button class="btn small" data-select-mission="${r.id}" data-go-missions>검토</button>`:'<button class="btn small" data-view="assets">보기</button>'}</div>`).join(''):`<div class="notice">현재 즉시 조치가 필요한 항목이 없습니다.</div>`}</div></div></article>`;}
function activeMissionStrip(active){const list=active.slice(0,3);return `<div class="card-head" style="padding-left:0;padding-right:0;border:0;background:transparent"><div class="card-title"><span class="card-icon">${icon('route')}</span><div><h2>진행 중 임무</h2><p>클릭하면 임무 상세로 이동합니다.</p></div></div><button class="btn small" data-view="missions">전체 임무</button></div><div class="mission-strip">${list.map(m=>{const o=locationById(m.originId),d=locationById(m.destinationId);return `<article class="mission-card" data-select-mission="${m.id}" data-go-missions><div class="mission-card-head"><div><span class="mono small">${m.id}</span> ${priorityBadge(m.priority)}</div>${statusBadge(m.status)}</div><h3>${escapeHtml(m.title)}</h3><p>${escapeHtml(m.cargo)} · ${fmt1(m.payloadKg,' kg')}</p><div class="route-mini"><span>${escapeHtml(o?.name||'-')}</span><i></i><span>${escapeHtml(d?.name||'-')}</span></div><div class="mission-progress"><div class="progress"><span style="width:${clamp(m.progress,0,100)}%"></span></div><b>${fmt1(m.progress,'%')}</b></div></article>`}).join('')||'<div class="notice">현재 진행 중 임무가 없습니다.</div>'}</div>`;}
function telemetryTable(){const rows=state.drones.map(d=>({d,t:latestTelemetry(d.id),b:batteryById(d.batteryId)}));return `<div class="card-head"><div class="card-title"><span class="card-icon">${icon('drone')}</span><div><h2>기체 실시간 데이터</h2><p>운영 수치는 소수점 한 자리, 위치는 정밀 좌표 형식으로 표시</p></div></div><button class="btn small" data-view="records">전체 기록</button></div><div class="table-wrap"><table class="table"><thead><tr><th>기체</th><th>상태</th><th>최종 수신</th><th>고도</th><th>속도</th><th>배터리</th><th>온도</th><th>통신</th><th>GNSS</th><th>위치</th></tr></thead><tbody>${rows.map(({d,t,b})=>`<tr><td><strong>${escapeHtml(d.name)}</strong><small>${d.id} · ${escapeHtml(d.model)}</small></td><td>${statusBadge(['IN_FLIGHT','RETURNING','HOLDING'].includes(d.status)?d.status:d.status==='READY'?'READY':d.status==='MAINTENANCE'?'CANCELLED':'READY')}</td><td><span class="data-fresh ${t&&elapsedSec(t.receivedAt)<=15?'':'stale'}"><i></i>${t?fmtTime(t.receivedAt,true):'-'}</span></td><td class="mono">${fmt1(d.altitudeM,' m')}</td><td class="mono">${fmt1(d.groundSpeedKmh,' km/h')}</td><td class="mono">${fmt1(b?.soc,'%')}</td><td class="mono">${fmt1(b?.temperatureC,' ℃')}</td><td class="mono">${fmt1(d.linkQualityPct,'%')}</td><td class="mono">${fmt1(d.satellites,'개')}</td><td><strong>${coordToDms(d.lat,true)}</strong><small>${coordToDms(d.lng,false)}</small></td></tr>`).join('')}</tbody></table></div>`;}
function missionsView(){const q=missionQuery.trim().toLowerCase(),rows=state.missions.filter(m=>(missionFilter==='ALL'||m.status===missionFilter)&&(!q||`${m.id} ${m.orderNo} ${m.title} ${m.cargo} ${m.recipient}`.toLowerCase().includes(q))),selected=missionById(state.ui.selectedMissionId)||rows[0];return `${pageHead('MISSION MANAGEMENT','배송임무 관리','등록부터 승인·점검·비행·복귀·증빙까지 모든 단계의 사용자와 시각을 기록합니다.',`<button class="btn" data-export-xlsx>${icon('download')} 운영보고서 XLSX</button><button class="btn primary" data-new-mission>${icon('plus')} 신규 임무</button>`)}<section class="split"><article class="card"><div class="toolbar"><div class="filters"><input class="input" id="mission-search" value="${escapeHtml(missionQuery)}" placeholder="임무·주문·화물·수령인 검색"><select class="select" id="mission-filter"><option value="ALL">전체 상태</option>${Object.entries(STATUS).map(([k,v])=>`<option value="${k}" ${missionFilter===k?'selected':''}>${v[0]}</option>`).join('')}</select></div><span class="muted small">검색 ${rows.length}건</span></div><div class="table-wrap"><table class="table"><thead><tr><th>임무</th><th>경로</th><th>화물</th><th>자원</th><th>상태</th><th>진행률</th><th>예정</th></tr></thead><tbody>${rows.map(m=>`<tr class="clickable ${selected?.id===m.id?'selected':''}" data-select-mission="${m.id}"><td><strong>${escapeHtml(m.title)}</strong><small>${m.id} · ${m.orderNo}</small></td><td><strong>${escapeHtml(locationById(m.originId)?.name||'-')}</strong><small>→ ${escapeHtml(locationById(m.destinationId)?.name||'-')} · ${fmt1(m.distanceKm,' km')}</small></td><td><strong>${escapeHtml(m.cargo)}</strong><small>${fmt1(m.payloadKg,' kg')} · ${escapeHtml(m.recipient)}</small></td><td><strong>${m.droneId||'미배정'}</strong><small>${m.batteryId||'배터리 미배정'} · ${escapeHtml(m.pilot)}</small></td><td>${statusBadge(m.status)}</td><td><strong>${fmt1(m.progress,'%')}</strong><div class="progress" style="width:80px;margin-top:5px"><span style="width:${m.progress}%"></span></div></td><td><strong>${fmtTime(m.scheduledAt)}</strong><small>ETA ${fmtTime(m.etaAt)}</small></td></tr>`).join('')}</tbody></table></div></article>${missionDetail(selected)}</section>`;}
function missionDetail(m){if(!m)return '<article class="card detail-panel"><div class="card-body">임무를 선택해 주세요.</div></article>';const d=droneById(m.droneId),b=batteryById(m.batteryId),allDone=Object.values(m.checks).every(Boolean);return `<article class="card detail-panel"><div class="detail-hero"><div class="detail-hero-top"><span class="mono small">${m.id}</span>${statusBadge(m.status)}</div><h3>${escapeHtml(m.title)}</h3><p>${escapeHtml(locationById(m.originId)?.name||'-')} → ${escapeHtml(locationById(m.destinationId)?.name||'-')}</p></div><div class="detail-grid"><div class="detail-item"><span>기체 / 조종자</span><strong>${m.droneId||'미배정'} · ${escapeHtml(m.pilot)}</strong></div><div class="detail-item"><span>배터리</span><strong>${m.batteryId||'미배정'} · ${fmt1(b?.soc,'%')}</strong></div><div class="detail-item"><span>화물</span><strong>${escapeHtml(m.cargo)} · ${fmt1(m.payloadKg,' kg')}</strong></div><div class="detail-item"><span>수령인</span><strong>${escapeHtml(m.recipient)}</strong></div><div class="detail-item"><span>진행률 / ETA</span><strong>${fmt1(m.progress,'%')} · ${fmtTime(m.etaAt)}</strong></div><div class="detail-item"><span>통신 / GNSS</span><strong>${fmt1(d?.linkQualityPct,'%')} · ${fmt1(d?.satellites,'개')}</strong></div></div><div class="card-head"><div><h2>비행 전 안전점검</h2><p>${allDone?'전체 항목 완료':'모든 항목 완료 후 이륙 가능'}</p></div><button class="btn small" data-check-all="${m.id}">전체 점검</button></div><div class="checklist">${Object.entries(CHECK_LABELS).map(([key,label])=>`<button class="check-row ${m.checks[key]?'done':''}" data-toggle-check="${m.id}" data-check-key="${key}"><span class="check-box">${m.checks[key]?'✓':''}</span><span>${label}</span><small>${m.checks[key]?'완료':'확인 필요'}</small></button>`).join('')}</div><div class="detail-actions">${missionButtons(m,allDone)}</div><div class="card-head"><div><h2>임무 이력</h2><p>행동 사용자와 발생시각 기록</p></div></div><div class="timeline">${[...m.history].reverse().slice(0,8).map(h=>`<div class="timeline-row"><i class="timeline-dot"></i><div><strong>${escapeHtml(h.event)}</strong><small>${escapeHtml(h.actor)} · ${fmtKST(h.at,true)}</small></div></div>`).join('')}</div></article>`;}
function missionButtons(m,allDone){if(m.status==='PENDING_APPROVAL')return `<button class="btn primary" data-mission-action="APPROVE" data-mission-id="${m.id}">${icon('check')} 운항 승인</button><button class="btn danger" data-mission-action="CANCEL" data-mission-id="${m.id}">취소</button>`;if(m.status==='READY')return `<button class="btn" data-auto-assign="${m.id}">자원 자동배정</button><button class="btn primary" data-mission-action="START" data-mission-id="${m.id}" ${!allDone||!m.droneId||!m.batteryId?'disabled':''}>${icon('play')} 이륙·임무 시작</button>`;if(m.status==='IN_FLIGHT'||m.status==='DELIVERING')return `<button class="btn warning" data-mission-action="HOLD" data-mission-id="${m.id}">${icon('pause')} 일시대기</button><button class="btn danger" data-mission-action="RTH" data-mission-id="${m.id}">${icon('rth')} 긴급 복귀</button><button class="btn green" data-mission-action="COMPLETE" data-mission-id="${m.id}">배송 완료</button>`;if(m.status==='HOLDING')return `<button class="btn primary" data-mission-action="RESUME" data-mission-id="${m.id}">${icon('play')} 운항 재개</button><button class="btn danger" data-mission-action="RTH" data-mission-id="${m.id}">${icon('rth')} 긴급 복귀</button>`;if(m.status==='RETURNING')return `<button class="btn green" data-mission-action="COMPLETE" data-mission-id="${m.id}">착륙·임무 종료</button>`;if(m.status==='COMPLETED')return `<button class="btn" data-view="records">${icon('record')} 배송증빙·기록 보기</button>`;return '';}
function assetsView(){return `${pageHead('FLEET & ENERGY','기체·스마트배터리','기체 운항가능성, 정비잔여시간과 배터리 SOC·SOH·온도·셀 편차를 한 자리 소수점으로 관리합니다.',`<button class="btn" data-export-xlsx>${icon('download')} 자산 포함 보고서</button>`)}<div class="card-head" style="padding-left:0;padding-right:0;border:0;background:transparent"><div class="card-title"><span class="card-icon">${icon('drone')}</span><div><h2>드론 기체</h2><p>운항·통신·정비 상태</p></div></div></div><section class="grid entity-grid">${state.drones.map(d=>{const b=batteryById(d.batteryId);return `<article class="entity"><div class="entity-top"><div><h3>${escapeHtml(d.name)}</h3><p>${d.id} · ${escapeHtml(d.model)}</p></div>${statusBadge(['IN_FLIGHT','RETURNING','HOLDING'].includes(d.status)?d.status:d.status==='READY'?'READY':d.status==='MAINTENANCE'?'CANCELLED':'READY')}</div><div class="metrics"><div class="metric"><span>배터리</span><strong>${fmt1(b?.soc,'%')}</strong></div><div class="metric"><span>통신</span><strong>${fmt1(d.linkQualityPct,'%')}</strong></div><div class="metric"><span>GNSS</span><strong>${fmt1(d.satellites,'개')}</strong></div><div class="metric"><span>고도</span><strong>${fmt1(d.altitudeM,' m')}</strong></div><div class="metric"><span>속도</span><strong>${fmt1(d.groundSpeedKmh,' km/h')}</strong></div><div class="metric"><span>정비잔여</span><strong>${fmt1(d.maintenanceDueHours,' h')}</strong></div></div><div class="health-bar ${d.maintenanceDueHours<10?'danger':d.maintenanceDueHours<20?'warning':''}"><div class="health-bar-head"><span>정비 여유</span><b>${fmt1(clamp(d.maintenanceDueHours/40*100,0,100),'%')}</b></div><div class="progress"><span style="width:${clamp(d.maintenanceDueHours/40*100,0,100)}%"></span></div></div></article>`}).join('')}</section><div class="card-head section-gap" style="padding-left:0;padding-right:0;border:0;background:transparent"><div class="card-title"><span class="card-icon">${icon('battery')}</span><div><h2>스마트배터리</h2><p>임무 투입 가능성 자동 판정</p></div></div></div><section class="grid entity-grid">${state.batteries.map(b=>{const risk=b.status==='QUARANTINE'||b.soh<85||b.cellDeltaMv>50;return `<article class="entity"><div class="entity-top"><div><h3>${b.id}</h3><p>${b.droneId?`${b.droneId} 장착`:'보관 랙'} · ${fmtKST(b.lastInspectionAt,false)}</p></div><span class="status ${risk?'red':b.status==='READY'?'green':'amber'}">${risk?'투입 차단':b.status==='READY'?'임무 적합':b.status}</span></div><div class="metrics"><div class="metric"><span>SOC</span><strong>${fmt1(b.soc,'%')}</strong></div><div class="metric"><span>SOH</span><strong>${fmt1(b.soh,'%')}</strong></div><div class="metric"><span>온도</span><strong>${fmt1(b.temperatureC,' ℃')}</strong></div><div class="metric"><span>셀 편차</span><strong>${fmt1(b.cellDeltaMv,' mV')}</strong></div><div class="metric"><span>사이클</span><strong>${fmt1(b.cycles,'회')}</strong></div><div class="metric"><span>예상비행</span><strong>${fmt1(b.soc*.42,'분')}</strong></div></div><div class="health-bar ${risk?'danger':b.soc<55?'warning':''}"><div class="health-bar-head"><span>충전 상태</span><b>${fmt1(b.soc,'%')}</b></div><div class="progress"><span style="width:${b.soc}%"></span></div></div></article>`}).join('')}</section>`;}
function safetyView(){const rows=[...state.alerts].sort((a,b)=>Number(a.acknowledged)-Number(b.acknowledged)||new Date(b.createdAt)-new Date(a.createdAt));return `${pageHead('SAFETY OPERATIONS','안전·경보 센터','발생시각, 현재값, 기준값, 확인자와 확인시각을 함께 기록합니다.',`<button class="btn" data-ack-all>전체 확인</button><button class="btn warning" data-test-alert>시험경보 생성</button>`)}<article class="card"><div class="table-wrap"><table class="table"><thead><tr><th>등급</th><th>발생시각</th><th>경보</th><th>대상</th><th>현재값</th><th>기준값</th><th>상태</th><th>조치</th></tr></thead><tbody>${rows.map(a=>`<tr><td><span class="status ${a.severity==='CRITICAL'?'red':a.severity==='WARNING'?'amber':'blue'}">${a.severity}</span></td><td><strong>${fmtKST(a.createdAt,true)}</strong><small>${fmt1(elapsedSec(a.createdAt),'초 전')}</small></td><td><strong>${escapeHtml(a.title)}</strong><small>${escapeHtml(a.message)}</small></td><td><strong>${a.droneId||a.batteryId||a.missionId||'운영센터'}</strong></td><td class="mono">${a.currentValue===null?'-':fmt1(a.currentValue,` ${a.unit}`)}</td><td class="mono">${a.threshold===null?'-':fmt1(a.threshold,` ${a.unit}`)}</td><td>${a.acknowledged?`<span class="status green">확인완료</span><small>${escapeHtml(a.acknowledgedBy||'')} · ${fmtKST(a.acknowledgedAt,true)}</small>`:'<span class="status red">미확인</span>'}</td><td>${a.acknowledged?'-':`<button class="btn small" data-ack-alert="${a.id}">확인 기록</button>`}</td></tr>`).join('')}</tbody></table></div></article>`;}
function recordRows(){const type=state.ui.recordType;if(type==='commands')return state.commandLogs.slice().reverse().map(x=>[fmtKST(x.requestedAt,true),x.id,x.missionId||'-',x.droneId||'-',x.command,x.status,x.result||'-',x.requestedBy]);if(type==='alerts')return state.alerts.map(x=>[fmtKST(x.createdAt,true),x.id,x.missionId||'-',x.droneId||x.batteryId||'-',x.title,x.severity,x.acknowledged?'확인':'미확인',x.acknowledgedBy||'-']);if(type==='checks')return state.checklistLogs.slice().reverse().map(x=>[fmtKST(x.checkedAt,true),x.id,x.missionId,'-',x.itemName,x.passed?'통과':'미통과',x.note||'-',x.checkedBy]);if(type==='battery')return state.batteryLogs.slice().reverse().map(x=>[fmtKST(x.recordedAt,true),x.id,x.missionId||'-',x.droneId||'-',`${x.batteryId} · SOC ${fmt1(x.soc,'%')}`,x.status,`SOH ${fmt1(x.soh,'%')} · ${fmt1(x.temperatureC,'℃')}`,fmt1(x.cellDeltaMv,'mV')]);if(type==='audit')return state.auditLogs.slice().reverse().map(x=>[fmtKST(x.occurredAt,true),x.id,x.targetId||'-',x.targetType,x.action,'기록',x.detail,x.actor]);return state.telemetryLogs.slice().reverse().slice(0,500).map(x=>[fmtKST(x.receivedAt,true),x.id,x.missionId||'-',x.droneId,`${fmt1(x.altitudeM,'m')} · ${fmt1(x.groundSpeedKmh,'km/h')}`,x.flightMode,`${fmt1(x.batterySocPct,'%')} · ${fmt1(x.linkQualityPct,'%')}`,`${coordToDms(x.lat,true)} / ${coordToDms(x.lng,false)}`]);}
function recordsView(){const tabs=[['telemetry','비행로그'],['commands','명령이력'],['alerts','경보이력'],['checks','점검표'],['battery','배터리기록'],['audit','감사로그']],rows=recordRows();return `${pageHead('OPERATION RECORDS','운영기록·보고서','날짜·시간·Mission ID·기체·수치·사용자·조치 결과를 자동 축적하고 다중시트 Excel로 내보냅니다.',`<button class="btn" data-export-json>${icon('download')} JSON 백업</button><button class="btn primary" data-export-xlsx>${icon('download')} 9시트 XLSX</button>`)}<article class="card"><div class="record-tabs">${tabs.map(([id,label])=>`<button class="tab ${state.ui.recordType===id?'active':''}" data-record-type="${id}">${label}</button>`).join('')}</div><div class="table-wrap"><table class="table"><thead><tr><th>기준시각(KST)</th><th>기록ID</th><th>Mission ID</th><th>기체/대상</th><th>수치·내용</th><th>상태</th><th>결과·세부</th><th>사용자/위치</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td class="${i<4?'mono':''}">${escapeHtml(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></article>`;}
function settingsView(){return `${pageHead('SYSTEM CONFIGURATION','시스템 설정','무료 지도, 기록 주기, 데이터 보관과 표시 기준을 관리합니다.',`<button class="btn" data-export-json>${icon('download')} 전체 백업</button>`)}<section class="settings-stack"><article class="card"><div class="card-head"><div class="card-title"><span class="card-icon">${icon('map')}</span><div><h2>지도 설정</h2><p>카카오맵 무료 쿼터 우선 · 실패 시 무료 OSM 자동전환</p></div></div></div><div class="setting-row"><div class="setting-copy"><strong>기본 지도</strong><small>Google Maps는 결제계정 연결이 필요하므로 무과금 우선 버전에서는 제외했습니다.</small></div><div class="setting-control"><select id="setting-map-provider" class="select"><option value="kakao" ${state.settings.mapProvider==='kakao'?'selected':''}>카카오맵 무료 쿼터 모드</option><option value="osm" ${state.settings.mapProvider==='osm'?'selected':''}>OpenStreetMap 무료 대체지도</option></select></div></div><div class="setting-row"><div class="setting-copy"><strong>카카오 JavaScript Key</strong><small>키는 이 브라우저에만 저장됩니다. 카카오 개발자센터에서 localhost:5500과 실제 배포 도메인을 등록해야 합니다.</small></div><div class="setting-control"><input id="setting-kakao-key" class="input mono" type="password" value="${escapeHtml(state.settings.kakaoJavaScriptKey)}" placeholder="JavaScript Key 입력"></div></div><div class="card-body"><div class="notice warning">비용 방지 원칙: 카카오맵 무료 쿼터 적용 대상 앱만 사용하고 Biz Wallet·유료 API 사용을 연결하지 않습니다. 무료 쿼터를 사용할 수 없거나 지도가 로딩되지 않으면 OpenStreetMap으로 자동 전환합니다.</div></div></article><article class="card"><div class="card-head"><div class="card-title"><span class="card-icon">${icon('record')}</span><div><h2>정밀 기록 기준</h2><p>실시간 데이터와 보고서의 공통 규칙</p></div></div></div><div class="setting-row"><div class="setting-copy"><strong>운영 수치 소수점</strong><small>고도·속도·거리·배터리·온도·통신·풍속·셀 편차는 소수점 한 자리로 저장·표시합니다.</small></div><div class="setting-control"><input class="input" value="1자리 고정" disabled></div></div><div class="setting-row"><div class="setting-copy"><strong>좌표 표시</strong><small>화면에서는 도·분·초의 초 단위만 소수점 한 자리로 표시합니다. Excel 원본 좌표는 안전 분석을 위해 WGS84 6자리로 저장합니다.</small></div><div class="setting-control"><input class="input" value="DMS 0.1초 / 원본 6자리" disabled></div></div><div class="setting-row"><div class="setting-copy"><strong>텔레메트리 기록주기</strong><small>시뮬레이션에서 위치·고도·속도·배터리·통신 수치를 기록하는 간격입니다.</small></div><div class="setting-control"><select id="setting-log-interval" class="select"><option value="5" ${state.settings.telemetryIntervalSec===5?'selected':''}>5초</option><option value="10" ${state.settings.telemetryIntervalSec===10?'selected':''}>10초</option><option value="30" ${state.settings.telemetryIntervalSec===30?'selected':''}>30초</option></select></div></div><div class="setting-row"><div class="setting-copy"><strong>시간 기준</strong><small>화면과 Excel은 Asia/Seoul(KST), 원본 데이터는 ISO 8601 UTC를 함께 유지합니다.</small></div><div class="setting-control"><input class="input" value="Asia/Seoul (KST)" disabled></div></div></article><article class="card"><div class="card-head"><div class="card-title"><span class="card-icon">${icon('settings')}</span><div><h2>저장·초기화</h2><p>현재 버전은 브라우저 로컬 저장 방식</p></div></div></div><div class="setting-row"><div class="setting-copy"><strong>설정 저장</strong><small>지도 키, 지도 종류와 기록주기를 저장하고 화면을 다시 구성합니다.</small></div><div class="setting-control"><button class="btn primary wide" data-save-settings>설정 저장·지도 다시 연결</button></div></div><div class="setting-row"><div class="setting-copy"><strong>데모 데이터 초기화</strong><small>생성한 임무와 기록을 삭제하고 최초 시연 데이터로 복원합니다.</small></div><div class="setting-control"><button class="btn danger wide" data-reset>데모 데이터 초기화</button></div></div><div class="card-body"><div class="notice">실제 다중 사용자 운영, 법적 보존, 서버 수신시각 보장은 다음 단계에서 PostgreSQL 등 서버 데이터베이스와 계정·권한·감사로그 서버를 연결해야 합니다.</div></div></article></section>`;}
function pilotView(){const mission=state.missions.find(m=>m.pilot==='김도윤'&&['READY','IN_FLIGHT','HOLDING','DELIVERING','RETURNING'].includes(m.status))||activeMissions()[0]||state.missions.find(m=>m.status==='READY');if(!mission)return `<main class="mobile-shell"><div class="mobile-hero"><div class="mobile-title"><h1>배정된 임무가 없습니다.</h1></div></div></main>`;const d=droneById(mission.droneId),b=batteryById(mission.batteryId),done=Object.values(mission.checks).filter(Boolean).length,total=Object.keys(CHECK_LABELS).length,next=mission.status==='READY'?(done===total?'이륙·임무 시작':'비행 전 점검 완료'):mission.status==='HOLDING'?'운항 재개':mission.status==='RETURNING'?'복귀 상태 확인':'운항 상세 확인';return `<main class="mobile-shell"><section class="mobile-hero"><div class="mobile-top"><div class="brand" style="padding:0"><div class="brand-mark">${icon('drone')}</div><div class="brand-copy"><strong>D-LOGIS PILOT</strong><small>현장 운항 앱</small></div></div><button class="btn icon" data-role-menu>${icon('user')}</button></div><div class="mobile-title"><small>안녕하세요, 김도윤 조종자님</small><h1>다음 작업을 확인해 주세요.</h1></div></section><div class="mobile-content"><article class="mobile-card"><div class="mobile-card-body"><div class="mission-card-head"><div><span class="mono small">${mission.id}</span> ${priorityBadge(mission.priority)}</div>${statusBadge(mission.status)}</div><h2 style="margin-top:10px">${escapeHtml(mission.title)}</h2><div class="mobile-route"><div class="stop"><span>출발지</span><strong>${escapeHtml(locationById(mission.originId)?.name||'-')}</strong></div><div class="route-drone">${icon('drone')}</div><div class="stop"><span>도착지</span><strong>${escapeHtml(locationById(mission.destinationId)?.name||'-')}</strong></div></div><div class="mobile-metrics"><div class="mobile-metric"><span>고도</span><strong>${fmt1(d?.altitudeM,'m')}</strong></div><div class="mobile-metric"><span>속도</span><strong>${fmt1(d?.groundSpeedKmh,'km/h')}</strong></div><div class="mobile-metric"><span>배터리</span><strong>${fmt1(b?.soc,'%')}</strong></div><div class="mobile-metric"><span>통신</span><strong>${fmt1(d?.linkQualityPct,'%')}</strong></div></div></div></article><article class="mobile-card next-action"><small>현재 수행할 작업</small><h3>${next}</h3>${pilotPrimaryAction(mission,done===total)}</article><article class="mobile-card"><div class="card-head"><div><h2>비행 전 점검</h2><p>${done}/${total} 완료 · 점검시각 자동 기록</p></div></div><div class="checklist">${Object.entries(CHECK_LABELS).map(([key,label])=>`<button class="check-row ${mission.checks[key]?'done':''}" data-toggle-check="${mission.id}" data-check-key="${key}"><span class="check-box">${mission.checks[key]?'✓':''}</span><span>${label}</span><small>${mission.checks[key]?'완료':'점검'}</small></button>`).join('')}</div></article><article class="mobile-card"><div class="card-head"><div><h2>임무 정보</h2><p>${fmtTime(mission.scheduledAt)} 출발 예정</p></div></div><div class="detail-grid"><div class="detail-item"><span>화물</span><strong>${escapeHtml(mission.cargo)} · ${fmt1(mission.payloadKg,'kg')}</strong></div><div class="detail-item"><span>수령인</span><strong>${escapeHtml(mission.recipient)}</strong></div><div class="detail-item"><span>기체</span><strong>${d?.name||'미배정'}</strong></div><div class="detail-item"><span>배터리</span><strong>${mission.batteryId||'미배정'}</strong></div></div></article></div><nav class="bottom-nav"><div class="bottom-nav-inner"><button class="active">${icon('mission')}임무</button><button>${icon('check')}점검</button><button>${icon('drone')}관제</button><button>${icon('record')}메시지</button><button data-exit>${icon('user')}나가기</button></div></nav></main>`;}
function pilotPrimaryAction(m,allDone){if(m.status==='READY')return `<button class="btn wide" data-mission-action="START" data-mission-id="${m.id}" ${!allDone||!m.droneId||!m.batteryId?'disabled':''}>${icon('play')} 이륙·임무 시작</button>`;if(m.status==='HOLDING')return `<button class="btn wide" data-mission-action="RESUME" data-mission-id="${m.id}">${icon('play')} 운항 재개</button>`;if(['IN_FLIGHT','DELIVERING'].includes(m.status))return `<div class="actions"><button class="btn wide" data-mission-action="HOLD" data-mission-id="${m.id}">${icon('pause')} 일시대기</button><button class="btn danger wide" data-mission-action="RTH" data-mission-id="${m.id}">${icon('rth')} 긴급 복귀</button></div>`;return `<button class="btn wide" data-enter-role="admin">관제센터 상세보기</button>`;}
function recipientView(){const mission=state.missions.find(m=>['IN_FLIGHT','HOLDING','DELIVERING'].includes(m.status))||state.missions[0],d=droneById(mission.droneId),etaMin=Math.max(0,round1((new Date(mission.etaAt)-Date.now())/60000));return `<main class="mobile-shell"><section class="mobile-hero"><div class="mobile-top"><div class="brand" style="padding:0"><div class="brand-mark">${icon('drone')}</div><div class="brand-copy"><strong>D-LOGIS DELIVERY</strong><small>안전한 드론 배송</small></div></div><button class="btn icon" data-role-menu>${icon('user')}</button></div><div class="mobile-title"><small>${mission.orderNo}</small><h1>드론이 배송 중입니다.</h1></div></section><div class="mobile-content"><article class="mobile-card"><div class="mobile-card-body"><div class="mission-card-head"><div><span class="muted small">예상 도착시간</span><div style="font-size:2rem;font-weight:900;margin-top:5px">${fmt1(etaMin,'분')}</div><span class="small muted">${fmtTime(mission.etaAt)} 도착 예정</span></div>${statusBadge(mission.status)}</div><div class="mission-progress"><div class="progress"><span style="width:${mission.progress}%"></span></div><b>${fmt1(mission.progress,'%')}</b></div></div></article><article class="mobile-card"><div class="mobile-card-body"><div class="mission-card-head"><h2>배송 수령코드</h2><span class="status blue">도착 시 사용</span></div><div class="otp">${String(mission.otp).split('').map(n=>`<i>${n}</i>`).join('')}</div><button class="btn wide" data-copy-otp="${mission.otp}">${icon('copy')} 코드 복사</button></div></article><article class="mobile-card"><div class="card-head"><div><h2>배송 상세정보</h2><p>실시간 관제센터 연결</p></div><span class="status green">정상</span></div><div class="detail-grid"><div class="detail-item"><span>배송 품목</span><strong>${escapeHtml(mission.cargo)}</strong></div><div class="detail-item"><span>배송 중량</span><strong>${fmt1(mission.payloadKg,'kg')}</strong></div><div class="detail-item"><span>비행 기체</span><strong>${escapeHtml(d?.name||'배정 중')}</strong></div><div class="detail-item"><span>예상 도착</span><strong>${fmtTime(mission.etaAt)}</strong></div></div></article><article class="mobile-card"><div class="card-head"><div><h2>안전 수령 안내</h2><p>${escapeHtml(locationById(mission.destinationId)?.name||'지정 배달점')}</p></div></div><div class="card-body"><div class="notice">드론이 착륙하거나 화물함 개방 안내가 나오기 전에는 지정 안전선 밖에서 대기해 주세요.</div></div></article></div><nav class="bottom-nav"><div class="bottom-nav-inner"><button class="active">${icon('mission')}배송</button><button>${icon('map')}경로</button><button>${icon('copy')}수령코드</button><button>${icon('record')}문의</button><button data-exit>${icon('user')}나가기</button></div></nav></main>`;}
function openMissionWizard(){missionDraftStep=1;const readyDrones=state.drones.filter(d=>d.airworthy&&d.status==='READY'),readyBatteries=state.batteries.filter(b=>b.status==='READY'&&b.soc>=60&&b.soh>=85&&b.cellDeltaMv<=50),local=new Date(Date.now()+30*60000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);$('#modal-root').innerHTML=`<div class="modal-backdrop" data-modal-close><section class="modal" onclick="event.stopPropagation()"><div class="modal-head"><div><h2>신규 배송임무</h2><p>4단계로 입력하고 자동 안전검토 후 Mission ID를 생성합니다.</p></div><button class="btn icon" data-modal-close>${icon('close')}</button></div><form id="mission-form"><div class="modal-body"><div class="wizard-steps">${['배송정보','경로·일정','자원배정','최종검토'].map((x,i)=>`<div class="wizard-step ${i===0?'active':''}" data-wizard-indicator="${i+1}">${i+1}. ${x}</div>`).join('')}</div><section class="wizard-page active" data-wizard-page="1"><div class="form-grid"><div class="field full"><label>임무명 <em>*</em></label><input class="input" name="title" required placeholder="예: 산업단지 긴급부품 배송"></div><div class="field"><label>배송 유형</label><select class="select" name="type"><option value="GENERAL">일반배송</option><option value="INDUSTRIAL">산업물류</option><option value="MEDICAL">의료연계</option><option value="EMERGENCY">재난긴급</option></select></div><div class="field"><label>우선순위</label><select class="select" name="priority"><option value="NORMAL">일반</option><option value="HIGH">우선</option><option value="URGENT">긴급</option></select></div><div class="field"><label>화물명 <em>*</em></label><input class="input" name="cargo" required></div><div class="field"><label>중량(kg) <em>*</em></label><input class="input" name="payloadKg" type="number" min=".1" max="10" step=".1" value="1.0" required></div><div class="field"><label>수령인·부서 <em>*</em></label><input class="input" name="recipient" required></div><div class="field"><label>연락처</label><input class="input" name="recipientPhone" value="010-0000-0000"></div></div></section><section class="wizard-page" data-wizard-page="2"><div class="form-grid"><div class="field"><label>출발지 <em>*</em></label><select class="select" name="originId">${state.locations.filter(l=>l.type==='HUB').map(l=>`<option value="${l.id}">${l.name}</option>`).join('')}</select></div><div class="field"><label>배송지 <em>*</em></label><select class="select" name="destinationId">${state.locations.filter(l=>l.type!=='HUB').map(l=>`<option value="${l.id}">${l.name}</option>`).join('')}</select></div><div class="field"><label>출발 예정시각 <em>*</em></label><input class="input" name="scheduledAt" type="datetime-local" value="${local}" required></div><div class="field"><label>수령 OTP</label><input class="input mono" name="otp" value="${Math.floor(100000+Math.random()*900000)}" readonly></div><div class="field full"><div class="notice">거리와 예상 비행시간은 출발지·도착지의 WGS84 좌표를 기준으로 자동 계산됩니다.</div></div></div></section><section class="wizard-page" data-wizard-page="3"><div class="form-grid"><div class="field"><label>조종자</label><select class="select" name="pilot"><option>김도윤</option><option>이현우</option><option>최민재</option></select></div><div class="field"><label>드론</label><select class="select" name="droneId"><option value="">자동배정 대기</option>${readyDrones.map(d=>`<option value="${d.id}">${d.name} · 최대 ${fmt1(d.payloadMaxKg,'kg')}</option>`).join('')}</select><div class="help">화물중량을 초과하는 기체는 생성 후 자동검토에서 차단됩니다.</div></div><div class="field"><label>배터리</label><select class="select" name="batteryId"><option value="">자동배정 대기</option>${readyBatteries.map(b=>`<option value="${b.id}">${b.id} · SOC ${fmt1(b.soc,'%')} · SOH ${fmt1(b.soh,'%')}</option>`).join('')}</select></div><div class="field"><label>기록주기</label><input class="input" value="${state.settings.telemetryIntervalSec}초" disabled></div></div></section><section class="wizard-page" data-wizard-page="4"><div id="mission-review" class="review-grid"></div><div class="notice warning" style="margin-top:13px">생성 직후 상태는 ‘승인대기’입니다. 관제 운영자가 승인하고 7개 안전점검을 완료해야 이륙할 수 있습니다.</div></section></div><div class="modal-foot"><button type="button" class="btn" data-modal-close>취소</button><button type="button" class="btn" data-wizard-prev disabled>이전</button><button type="button" class="btn primary" data-wizard-next>다음</button><button type="submit" class="btn primary hidden" data-wizard-submit>임무 생성</button></div></form></section></div>`;}
function updateWizard(step){missionDraftStep=step;$$('[data-wizard-page]').forEach(x=>x.classList.toggle('active',Number(x.dataset.wizardPage)===step));$$('[data-wizard-indicator]').forEach(x=>x.classList.toggle('active',Number(x.dataset.wizardIndicator)===step));$('[data-wizard-prev]').disabled=step===1;$('[data-wizard-next]').classList.toggle('hidden',step===4);$('[data-wizard-submit]').classList.toggle('hidden',step!==4);if(step===4){const fd=new FormData($('#mission-form')),o=state.locations.find(l=>l.id===fd.get('originId')),d=state.locations.find(l=>l.id===fd.get('destinationId'));$('#mission-review').innerHTML=[['임무명',fd.get('title')],['화물',`${fd.get('cargo')} · ${fmt1(fd.get('payloadKg'),'kg')}`],['경로',`${o?.name} → ${d?.name}`],['거리',fmt1(haversineKm(o,d),'km')],['출발예정',fmtKST(new Date(fd.get('scheduledAt')).toISOString(),false)],['조종자',fd.get('pilot')],['드론',fd.get('droneId')||'생성 후 자동배정'],['배터리',fd.get('batteryId')||'생성 후 자동배정']].map(([l,v])=>`<div class="review-item"><span>${l}</span><strong>${escapeHtml(v)}</strong></div>`).join('');}}
function validateWizardStep(step){const page=$(`[data-wizard-page="${step}"]`);for(const input of $$('input,select',page)){if(!input.reportValidity())return false;}return true;}
function createMission(form){const fd=new FormData(form),origin=locationById(fd.get('originId')),destination=locationById(fd.get('destinationId')),distance=haversineKm(origin,destination),scheduled=new Date(fd.get('scheduledAt')).toISOString(),drone=droneById(fd.get('droneId')),payload=round1(fd.get('payloadKg'));if(drone&&payload>drone.payloadMaxKg)return toast('기체 배정 실패',`화물 ${fmt1(payload,'kg')}이 ${drone.name} 최대 탑재량을 초과합니다.`,'error');const m={id:`MSN-${new Intl.DateTimeFormat('sv-SE',{timeZone:TIME_ZONE}).format(new Date()).replaceAll('-','')}-${String(state.missions.length+1).padStart(3,'0')}`,orderNo:`ORD-${Date.now().toString().slice(-10)}`,title:fd.get('title'),type:fd.get('type'),priority:fd.get('priority'),status:'PENDING_APPROVAL',progress:0,originId:origin.id,destinationId:destination.id,droneId:fd.get('droneId')||null,batteryId:fd.get('batteryId')||null,pilot:fd.get('pilot'),cargo:fd.get('cargo'),payloadKg:payload,recipient:fd.get('recipient'),recipientPhone:fd.get('recipientPhone'),otp:fd.get('otp'),distanceKm:distance,scheduledAt:scheduled,createdAt:nowIso(),approvedAt:null,departedAt:null,etaAt:new Date(new Date(scheduled).getTime()+Math.ceil(distance/34*60)*60000).toISOString(),completedAt:null,onTime:null,checks:{weather:false,airspace:false,airframe:false,battery:false,cargo:false,link:false,route:false},history:[{event:'임무 생성',at:nowIso(),actor:state.session.operatorName}]};state.missions.unshift(m);state.ui.selectedMissionId=m.id;state.ui.view='missions';logAudit('MISSION_CREATE','MISSION',m.id,`${m.title} · ${m.cargo} · ${fmt1(m.payloadKg,'kg')}`);addAlert({severity:m.priority==='URGENT'?'CRITICAL':'WARNING',category:'MISSION',title:'신규 임무 승인 필요',message:`${m.id} · ${m.title}`,missionId:m.id});persist();$('#modal-root').innerHTML='';render();toast('배송임무 생성 완료',`${m.id}가 승인대기로 등록되었습니다.`,'success');}
function toggleCheck(id,key){const m=missionById(id);if(!m)return;m.checks[key]=!m.checks[key];const item={id:uid('CHK'),missionId:id,itemKey:key,itemName:CHECK_LABELS[key],passed:m.checks[key],checkedAt:nowIso(),checkedBy:state.session.role==='pilot'?'김도윤':state.session.operatorName,note:m.checks[key]?'점검 완료':'점검 해제'};pushLog(state.checklistLogs,item);m.history.push({event:`${CHECK_LABELS[key]} ${m.checks[key]?'완료':'해제'}`,at:item.checkedAt,actor:item.checkedBy});logAudit('PREFLIGHT_CHECK','MISSION',id,`${CHECK_LABELS[key]}: ${m.checks[key]?'완료':'해제'}`,item.checkedBy);persist();render();}
function completeAllChecks(id){const m=missionById(id);if(!m)return;const at=nowIso(),actor=state.session.role==='pilot'?'김도윤':state.session.operatorName;Object.keys(m.checks).forEach(key=>{if(!m.checks[key])pushLog(state.checklistLogs,{id:uid('CHK'),missionId:id,itemKey:key,itemName:CHECK_LABELS[key],passed:true,checkedAt:at,checkedBy:actor,note:'전체 점검 실행'});m.checks[key]=true;});m.history.push({event:'비행 전 전체 점검 완료',at,actor});logAudit('PREFLIGHT_ALL','MISSION',id,'7개 안전점검 전체 완료',actor);persist();render();toast('비행 전 점검 완료','점검자와 완료시각이 기록되었습니다.','success');}
function autoAssign(id){const m=missionById(id);if(!m)return;const d=state.drones.find(x=>x.airworthy&&x.status==='READY'&&x.payloadMaxKg>=m.payloadKg),b=state.batteries.find(x=>x.status==='READY'&&x.soc>=60&&x.soh>=85&&x.cellDeltaMv<=50);if(!d||!b)return toast('자동배정 불가','화물중량과 안전기준을 만족하는 기체 또는 배터리가 없습니다.','error');m.droneId=d.id;m.batteryId=b.id;m.pilot=m.pilot==='미배정'?'김도윤':m.pilot;d.batteryId=b.id;b.droneId=d.id;m.history.push({event:`자원 자동배정 · ${d.id} / ${b.id}`,at:nowIso(),actor:state.session.operatorName});logAudit('AUTO_ASSIGN','MISSION',id,`${d.id} · ${b.id}`);persist();render();toast('자원 자동배정 완료',`${d.name}과 ${b.id}를 배정했습니다.`,'success');}
function commandLog(m,command,result='APPLIED'){const now=nowIso(),id=uid('CMD'),actor=state.session.role==='pilot'?'김도윤':state.session.operatorName,item={id,missionId:m.id,droneId:m.droneId,command,requestedBy:actor,requestedAt:now,sentAt:now,acknowledgedAt:new Date(Date.now()+180).toISOString(),appliedAt:new Date(Date.now()+420).toISOString(),status:result,result:state.settings.mode==='simulation'?'SIMULATION_ACCEPTED':'MAV_RESULT_ACCEPTED'};pushLog(state.commandLogs,item);logAudit('COMMAND','MISSION',m.id,`${command} · ${item.result}`,actor);return item;}
function missionAction(id,action){const m=missionById(id);if(!m)return;const actor=state.session.role==='pilot'?'김도윤':state.session.operatorName;if(['RTH','CANCEL'].includes(action)&&!confirm(`${action==='RTH'?'긴급 복귀':'임무 취소'}를 실행하시겠습니까?\n사용자와 실행시각이 기록됩니다.`))return;if(action==='APPROVE'){m.status='READY';m.approvedAt=nowIso();m.history.push({event:'운항 승인',at:m.approvedAt,actor});commandLog(m,'APPROVE');}if(action==='CANCEL'){m.status='CANCELLED';m.history.push({event:'임무 취소',at:nowIso(),actor});commandLog(m,'CANCEL');}if(action==='START'){if(!m.droneId||!m.batteryId)return toast('이륙 차단','기체와 배터리를 먼저 배정하세요.','error');if(!Object.values(m.checks).every(Boolean))return toast('이륙 차단','7개 비행 전 점검을 모두 완료하세요.','error');const d=droneById(m.droneId),b=batteryById(m.batteryId);if(!d?.airworthy||!b||b.status==='QUARANTINE'||b.soc<40)return toast('이륙 차단','기체 또는 배터리가 임무 투입 기준을 충족하지 않습니다.','error');m.status='IN_FLIGHT';m.departedAt=nowIso();m.history.push({event:'이륙·임무 시작',at:m.departedAt,actor});d.status='IN_FLIGHT';d.missionId=m.id;d.armed=true;d.flightMode='MISSION';d.payloadKg=m.payloadKg;b.status='IN_USE';commandLog(m,'START');}if(action==='HOLD'){m.status='HOLDING';m.history.push({event:'일시대기',at:nowIso(),actor});const d=droneById(m.droneId);if(d){d.status='HOLDING';d.flightMode='HOLD';d.groundSpeedKmh=0;}commandLog(m,'HOLD');}if(action==='RESUME'){m.status='IN_FLIGHT';m.history.push({event:'운항 재개',at:nowIso(),actor});const d=droneById(m.droneId);if(d){d.status='IN_FLIGHT';d.flightMode='MISSION';}commandLog(m,'RESUME');}if(action==='RTH'){m.status='RETURNING';m.returnProgress=0;m.history.push({event:'긴급 복귀 명령',at:nowIso(),actor});const d=droneById(m.droneId);if(d){d.status='RETURNING';d.flightMode='RTL';d.payloadKg=0;}commandLog(m,'RTH');}if(action==='COMPLETE'){m.status='COMPLETED';m.progress=100;m.completedAt=nowIso();m.onTime=new Date(m.completedAt)<=new Date(m.etaAt);m.history.push({event:'착륙·임무 종료',at:m.completedAt,actor});const d=droneById(m.droneId),b=batteryById(m.batteryId),origin=locationById(m.originId),dest=locationById(m.destinationId);if(d){d.status='READY';d.missionId=null;d.armed=false;d.flightMode='STANDBY';d.altitudeM=0;d.groundSpeedKmh=0;d.payloadKg=0;d.lat=origin.lat;d.lng=origin.lng;}if(b){b.status=b.soc>=40?'READY':'CHARGING';b.droneId=d?.id||null;}if(!state.proofs.some(p=>p.missionId===m.id))state.proofs.unshift({id:uid('PRF'),missionId:m.id,orderNo:m.orderNo,recipient:m.recipient,method:'OTP+화물함 개폐',otpMatched:true,lockerOpenedAt:m.completedAt,deliveredAt:m.completedAt,lat:dest.lat,lng:dest.lng,photoFileName:`POD_${m.id}.jpg`,signature:'전자 인수확인 완료',temperatureMinC:round1(22+Math.random()),temperatureMaxC:round1(24+Math.random())});commandLog(m,'COMPLETE');}persist();render();toast('임무 상태 변경',`${m.id} · ${STATUS[m.status]?.[0]||m.status}`,'success');}
function acknowledgeAlert(id){const a=state.alerts.find(x=>x.id===id);if(!a)return;a.acknowledged=true;a.acknowledgedAt=nowIso();a.acknowledgedBy=state.session.operatorName;logAudit('ALERT_ACK','ALERT',id,a.title);persist();render();toast('경보 확인 기록 완료',`${a.acknowledgedBy} · ${fmtKST(a.acknowledgedAt,true)}`,'success');}
function saveSettings(){state.settings.mapProvider=$('#setting-map-provider')?.value||state.settings.mapProvider;state.settings.kakaoJavaScriptKey=$('#setting-kakao-key')?.value.trim()||'';state.settings.telemetryIntervalSec=Number($('#setting-log-interval')?.value||5);persist();render();toast('설정 저장 완료',state.settings.mapProvider==='kakao'?'카카오맵 무료모드로 다시 연결합니다.':'OpenStreetMap을 사용합니다.','success');}
function simulationLoop(){if(state.settings.mode!=='simulation')return;const now=Date.now(),interval=state.settings.telemetryIntervalSec*1000;if(now-lastSimulationAt<interval)return;lastSimulationAt=now;let changed=false;activeMissions().forEach(m=>{const d=droneById(m.droneId),b=batteryById(m.batteryId),o=locationById(m.originId),dest=locationById(m.destinationId);if(!d||!o||!dest)return;if(m.status==='IN_FLIGHT'||m.status==='DELIVERING'){m.progress=round1(clamp(m.progress+1.2,0,97));if(m.progress>=78)m.status='DELIVERING';const p=m.progress/100;d.lat=roundCoord(o.lat+(dest.lat-o.lat)*p);d.lng=roundCoord(o.lng+(dest.lng-o.lng)*p);d.altitudeM=round1(78+Math.sin(now/5000)*7);d.groundSpeedKmh=round1(34+Math.sin(now/3000)*4);d.headingDeg=round1(105+Math.sin(now/7000)*12);}else if(m.status==='RETURNING'){m.returnProgress=round1(clamp((m.returnProgress||0)+1.3,0,98));const p=1-m.returnProgress/100;d.lat=roundCoord(o.lat+(dest.lat-o.lat)*p);d.lng=roundCoord(o.lng+(dest.lng-o.lng)*p);d.altitudeM=round1(Math.max(18,74-m.returnProgress*.45));d.groundSpeedKmh=round1(39+Math.sin(now/3500)*3);}else if(m.status==='HOLDING'){d.groundSpeedKmh=0;d.altitudeM=round1(d.altitudeM);}d.linkQualityPct=round1(clamp(d.linkQualityPct+(Math.random()-.5)*2,55,100));d.satellites=round1(clamp(d.satellites+(Math.random()>.7?(Math.random()>.5?1:-1):0),12,26));if(b){b.soc=round1(clamp(b.soc-.2,5,100));b.temperatureC=round1(clamp(b.temperatureC+(Math.random()-.35)*.15,25,49));d.batterySocPct=b.soc;if(b.soc<24)addAlert({severity:'WARNING',category:'BATTERY',title:`${d.name} 배터리 안전여유 감소`,message:`현재 SOC ${fmt1(b.soc,'%')}입니다. 복귀 가능시간을 확인하세요.`,missionId:m.id,droneId:d.id,batteryId:b.id,currentValue:b.soc,threshold:24,unit:'%'});}if(d.linkQualityPct<65)addAlert({severity:'CRITICAL',category:'LINK',title:`${d.name} 통신품질 저하`,message:`현재 통신품질 ${fmt1(d.linkQualityPct,'%')}입니다.`,missionId:m.id,droneId:d.id,currentValue:d.linkQualityPct,threshold:65,unit:'%'});createTelemetry(d,m);changed=true;});if(changed){persist();if(state.session.role&&['admin','pilot','recipient'].includes(state.session.role))render();}}
function updateClock(){const c=$('#live-clock'),d=$('#live-date');if(c)c.textContent=fmtTime(nowIso(),true);if(d)d.textContent=fmtDate(nowIso());}
function setRole(role){state.session.role=role;if(role==='admin'){state.session.operatorName='한지수';state.session.operatorRole='관제운영 책임자';state.ui.view='dashboard';}if(role==='pilot'){state.session.operatorName='김도윤';state.session.operatorRole='현장 조종자';}if(role==='recipient'){state.session.operatorName='박서연';state.session.operatorRole='배송 수령인';}persist();render();}
document.addEventListener('click',e=>{const t=e.target.closest('button,[data-select-mission],[data-go-missions]');if(!t)return;if(t.dataset.enterRole)return setRole(t.dataset.enterRole);if(t.dataset.exit!==undefined){state.session.role=null;persist();return render();}if(t.dataset.sidebarToggle!==undefined){state.ui.sidebarOpen=!state.ui.sidebarOpen;persist();return render();}if(t.dataset.view){state.session.role='admin';state.ui.view=t.dataset.view;state.ui.sidebarOpen=false;persist();return render();}if(t.dataset.newMission!==undefined)return openMissionWizard();if(t.dataset.modalClose!==undefined){$('#modal-root').innerHTML='';return;}if(t.dataset.wizardNext!==undefined){if(!validateWizardStep(missionDraftStep))return;return updateWizard(Math.min(4,missionDraftStep+1));}if(t.dataset.wizardPrev!==undefined)return updateWizard(Math.max(1,missionDraftStep-1));if(t.dataset.selectMission){state.ui.selectedMissionId=t.dataset.selectMission;if(t.dataset.goMissions!==undefined){state.session.role='admin';state.ui.view='missions';}persist();return render();}if(t.dataset.toggleCheck)return toggleCheck(t.dataset.toggleCheck,t.dataset.checkKey);if(t.dataset.checkAll)return completeAllChecks(t.dataset.checkAll);if(t.dataset.autoAssign)return autoAssign(t.dataset.autoAssign);if(t.dataset.missionAction)return missionAction(t.dataset.missionId,t.dataset.missionAction);if(t.dataset.ackAlert)return acknowledgeAlert(t.dataset.ackAlert);if(t.dataset.ackAll!==undefined){state.alerts.filter(a=>!a.acknowledged).forEach(a=>{a.acknowledged=true;a.acknowledgedAt=nowIso();a.acknowledgedBy=state.session.operatorName;});logAudit('ALERT_ACK_ALL','ALERT','ALL','전체 경보 확인');persist();render();return toast('전체 경보 확인 완료','확인자와 시각이 기록되었습니다.','success');}if(t.dataset.testAlert!==undefined){addAlert({severity:'WARNING',category:'LINK',title:'통신품질 시험경보',message:'화면·기록 검증을 위한 시험 경보입니다.',droneId:'DR-003',currentValue:62.4,threshold:65,unit:'%'});persist();render();return toast('시험경보 생성','안전·경보 센터에 기록했습니다.','warning');}if(t.dataset.recordType){state.ui.recordType=t.dataset.recordType;persist();return render();}if(t.dataset.exportXlsx!==undefined)return exportOperationalWorkbook();if(t.dataset.exportJson!==undefined)return exportJsonBackup();if(t.dataset.openKakao!==undefined)return DLogisMap.openInKakao();if(t.dataset.saveSettings!==undefined)return saveSettings();if(t.dataset.reset!==undefined){if(confirm('현재 브라우저의 모든 임무·로그·설정을 초기화하시겠습니까?')){localStorage.removeItem(STORAGE_KEY);state=seedState();persist();render();toast('초기화 완료','최초 시연 데이터로 복원했습니다.','success');}return;}if(t.dataset.copyOtp){navigator.clipboard?.writeText(t.dataset.copyOtp);return toast('수령코드 복사 완료',t.dataset.copyOtp,'success');}if(t.dataset.roleMenu!==undefined){state.session.role=null;persist();return render();}});
document.addEventListener('input',e=>{if(e.target.id==='mission-search'){missionQuery=e.target.value;render();const input=$('#mission-search');input?.focus();input?.setSelectionRange(missionQuery.length,missionQuery.length);}});
document.addEventListener('change',e=>{if(e.target.id==='mission-filter'){missionFilter=e.target.value;render();}if(e.target.id==='quick-map-provider'){state.settings.mapProvider=e.target.value;persist();render();}});
document.addEventListener('submit',e=>{if(e.target.id==='mission-form'){e.preventDefault();createMission(e.target);}});
window.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modal-root').innerHTML='';});
window.addEventListener('load',()=>{if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});});
setInterval(updateClock,1000);setInterval(simulationLoop,1000);render();
